            jdbc.execute("DELETE FROM currency");
            jdbc.execute("INSERT INTO currency (code, symbol, rounding_step) VALUES ('USD', '$', 0.01), ('EUR', '€', 0.01),"
                    + " ('GBP', '£', 0.01), ('CAD', 'CA$', 0.01), ('AUD', 'A$', 0.01)");
